      badges: [fr(B.fromHi, 0) + ' % sous le sommet du 9 octobre', 'Base de sept séances entre ' + usd(abandon) + ' et ' + usd(entry), 'ATR de ' + usd(tech.atr14)],
      supports: [lv('stop'), lv('s2'), lv('s3')], resistances: [lv('r1'), lv('x1'), lv('r2')],
      setupNote: 'Clôture du 26 octobre à ' + usd(close) + ' (' + sgn(c26, 1) + '), en ligne avec le secteur ce jour-là (panier technologique ' + sgn(xlk26, 1) + ', semi-conducteurs ' + sgn(smh26, 1) + ', Dell ' + sgn(dell26, 1) + '), sur ' + fr(vol26 / 1e6, 1) + ' millions d’actions, le plus faible volume des vingt dernières séances. Depuis le 16 octobre, le titre tient dans une base de sept séances entre ' + usd(abandon) + ', plus bas du 22 octobre, et ' + usd(entry) + ', plus haut du 21. Il reste sous sa moyenne à vingt séances (' + usd(tech.ema20) + '), au niveau de celle à cinquante (' + usd(tech.ema50) + ') et loin au-dessus de celle à deux cents (' + usd(tech.ema200) + '), RSI à ' + fr(tech.rsi14, 0) + ', MACD sous son signal. Une clôture au-dessus de ' + usd(entry) + ' sortirait le titre de la base ; les obstacles suivants sont ' + usd(lv('r1')) + ', plus haut du 15 octobre, ' + usd(lv('x1')) + ', plus haut du 14, puis ' + usd(lv('r2')) + ', clôture du 13 octobre, point de départ de la chute ; au-dessus, ' + usd(lv('r3')) + ', sommet de la série. Sous ' + usd(stop) + ', les supports sont ' + usd(lv('s2')) + ', plus bas du 2 septembre, et ' + usd(lv('s3')) + ', plus bas du 3 septembre.',
